.deck { font-size: 1.22rem; max-width: 730px; color: var(--muted); }
.note { border-left: 3px solid var(--amber); padding: .3rem 0 .3rem 1.2rem; font-size: .92rem; }
.note strong { display: block; margin-bottom: .5rem; }
.actions { display: flex; flex-wrap: wrap; gap: .8rem; margin-top: 1.8rem; }
.button { display: inline-block; border: 1px solid var(--teal-dark); padding: .65rem 1rem; text-decoration: none; font-weight: 650; font-size: .92rem; }
.button.primary { background: var(--teal-dark); color: white; }
.button.primary:hover { background: var(--ink); }
main section { padding: 3.4rem 0; border-top: 1px solid var(--line); }
h2 { font-family: Georgia, serif; font-size: clamp(2rem, 4vw, 3rem); font-weight: 500; line-height: 1.1; letter-spacing: -.03em; margin: 0 0 1.4rem; }
