#!/usr/bin/env python3
"""Descriptive summaries for ILR reviewer responses.

This intentionally does not label one reviewer as correct or turn agreement into
validity. Input is UTF-8 JSON with a top-level `responses` array. See
calibration/responses.schema.json for field details.
"""

import argparse
import collections
import json
import math
import sys

FIELDS = (
    "event_class",
    "actual_impact",
    "potential_impact",
    "control_performance",
    "response_priority",
)


def validate_response(response, index):
    where = "responses[%d]" % index
    if not isinstance(response, dict):
        raise ValueError("%s must be an object" % where)
    for field in ("reviewer_id", "vignette_id"):
        if not isinstance(response.get(field), str) or not response[field]:
            raise ValueError("%s.%s must be a nonempty string" % (where, field))
    ratings = response.get("ratings")
    if not isinstance(ratings, dict):
        raise ValueError("%s.ratings must be an object" % where)
    for field in FIELDS:
        if not isinstance(ratings.get(field), str) or not ratings[field]:
            raise ValueError("%s.ratings.%s must be a nonempty string" % (where, field))


def validate(data):
    if not isinstance(data, dict) or not isinstance(data.get("responses"), list):
        raise ValueError("top level must be an object containing a responses array")
    seen = set()
    for index, response in enumerate(data["responses"]):
        validate_response(response, index)
        key = (response["reviewer_id"], response["vignette_id"])
        if key in seen:
            raise ValueError("duplicate reviewer/vignette pair: %r" % (key,))
        seen.add(key)
    return data["responses"]


def summarize(responses):
    grouped = collections.defaultdict(list)
    reviewers = set()
    for response in responses:
        grouped[response["vignette_id"]].append(response)
        reviewers.add(response["reviewer_id"])

    result = {
        "response_count": len(responses),
        "reviewer_count": len(reviewers),
        "vignette_count": len(grouped),
        "caution": (
            "Descriptive agreement only; not validity, accuracy, representativeness, "
            "or evidence of real-world reporting performance."
        ),
        "vignettes": {},
    }

    for vignette_id in sorted(grouped):
        items = grouped[vignette_id]
        summary = {
            "response_count": len(items),
            "unique_reviewer_count": len({x["reviewer_id"] for x in items}),
            "fields": {},
        }
        for field in FIELDS:
            values = [x["ratings"][field] for x in items]
            counts = collections.Counter(values)
            total = len(values)
            pairs = math.comb(total, 2)
            concordant_pairs = sum(math.comb(n, 2) for n in counts.values())
            summary["fields"][field] = {
                "counts": dict(sorted(counts.items())),
                "modal_values": sorted(k for k, n in counts.items() if n == max(counts.values())),
                "unanimous": len(counts) == 1,
                "pairwise_agreement": (concordant_pairs / pairs) if pairs else None,
            }
        result["vignettes"][vignette_id] = summary
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--responses", required=True, help="JSON response file")
    parser.add_argument("--output", help="Write JSON summary here instead of stdout")
    args = parser.parse_args()
    try:
        with open(args.responses, encoding="utf-8") as handle:
            responses = validate(json.load(handle))
        report = json.dumps(summarize(responses), indent=2, sort_keys=True) + "\n"
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        parser.exit(2, "error: %s\n" % exc)
    if args.output:
        with open(args.output, "w", encoding="utf-8") as handle:
            handle.write(report)
    else:
        sys.stdout.write(report)


if __name__ == "__main__":
    main()

